<?php
namespace Tests;
use App\Services\{SalonStore,Tenant,BookingPrepayments,BookingHorizon,Connections,PlatformConnections,SmsWallet,SimplePay};
use Carbon\CarbonImmutable as Time;
use Illuminate\Foundation\Testing\TestCase;
use Illuminate\Support\Facades\{Artisan,DB,Http,Mail,Cache};
use Illuminate\Support\Str;
final class PaymentPoliciesTest extends TestCase {
 private string $path;
 public function createApplication(){$a=require __DIR__.'/../bootstrap/app.php';$a->make(\Illuminate\Contracts\Console\Kernel::class)->bootstrap();return $a;}
 protected function setUp():void{parent::setUp();if(config('database.default')!=='sqlite'||config('database.connections.sqlite.database')!==':memory:')throw new \RuntimeException('In-memory database only.');Artisan::call('migrate',['--force'=>true]);Time::setTestNow('2036-05-06T06:00:00Z');$this->path=storage_path('framework/policies-'.bin2hex(random_bytes(6)));config(['integrations.path'=>$this->path,'operator.connections_path'=>$this->path.'-platform']);foreach(['salon_state','providers','deliveries','sms_ledger','sms_topups','sms_wallets','calendar_tasks','calendar_connections'] as $t)DB::table($t)->delete();foreach([1,2] as $id)DB::table('salon_state')->insert(['id'=>$id,'data'=>json_encode(SalonStore::initial())]);app(Tenant::class)->id=1;Cache::flush();Http::preventStrayRequests();Mail::fake();$this->withSession(['admin'=>true,'provider_id'=>1,'_token'=>str_repeat('p',40)])->withHeader('X-CSRF-TOKEN',str_repeat('p',40));}
 protected function tearDown():void{Time::setTestNow();foreach(glob($this->path.'*') as $file)if(is_file($file))unlink($file);parent::tearDown();}
 private function configure(array $extra=[]):void{app(SalonStore::class)->mutate(function(&$s)use($extra){$s['settings']=array_replace($s['settings'],['prepaymentEnabled'=>true,'prepaymentMode'=>'deposit','depositType'=>'percent','depositValue'=>30,'prepaymentAccountName'=>'Szalon','prepaymentAccount'=>'12345678-12345678','confirmation'=>false],$extra);$s['services'][0]['automatic']=true;});}
 private function data(array $extra=[]):array{return array_replace(['name'=>'Vendég','email'=>'guest@example.com','phone'=>'06301234567','staff'=>'anna','services'=>['cut'],'start'=>'2036-05-07T08:00:00Z','public'=>true],$extra);}
 private function config(array $extra=[]):array{return ['settings'=>array_replace(['name'=>'Szalon','profession'=>'Fodrászat','confirmation'=>false,'reminder'=>24,'channel'=>'email'],$extra)];}
 public function test_required_deposit_blocks_confirmation_until_actual_manual_payment_and_keeps_original_policy():void{
  $this->configure();$b=$this->postJson('/api/bookings',$this->data())->assertCreated()->assertJsonPath('awaitingPayment',true)->assertJsonPath('status','pending')->json();$this->assertSame(2550,$b['paymentRequirement']['amount']);
  $this->patchJson('/api/bookings/'.$b['id'],['status'=>'confirmed'])->assertUnprocessable();$this->postJson('/api/payments',['bookingId'=>$b['id'],'amount'=>2000,'method'=>'transfer','paidAt'=>now()->toISOString()])->assertCreated();$this->getJson('/api/manage?token='.$b['token'])->assertJsonPath('prepayment.requiredDue',550)->assertJsonPath('booking.status','pending');
  $this->configure(['depositValue'=>90]);$this->postJson('/api/payments',['bookingId'=>$b['id'],'amount'=>550,'method'=>'transfer','paidAt'=>now()->toISOString()])->assertCreated();$this->getJson('/api/manage?token='.$b['token'])->assertJsonPath('prepayment.requiredDue',0)->assertJsonPath('booking.awaitingPayment',false)->assertJsonPath('booking.status','confirmed');Mail::assertNothingSent();
 }
 public function test_payment_does_not_bypass_a_separate_provider_approval():void{$this->configure(['confirmation'=>true]);app(SalonStore::class)->mutate(function(&$s){$s['services'][0]['automatic']=false;});$b=$this->postJson('/api/bookings',$this->data())->assertCreated()->json();$this->postJson('/api/payments',['bookingId'=>$b['id'],'amount'=>2550,'method'=>'cash','paidAt'=>now()->toISOString()])->assertCreated();$this->getJson('/api/manage?token='.$b['token'])->assertJsonPath('booking.awaitingPayment',false)->assertJsonPath('booking.status','pending');$this->patchJson('/api/bookings/'.$b['id'],['status'=>'confirmed'])->assertOk();}
 public function test_mixed_service_overrides_allocate_discount_without_exceeding_price():void{
  $s=app(SalonStore::class)->read();$s['settings']=array_replace($s['settings'],['prepaymentMode'=>'full']);$b=['serviceSnapshot'=>[['price'=>10000,'prepaymentPolicy'=>'deposit','depositType'=>'percent','depositValue'=>25],['price'=>10000,'prepaymentPolicy'=>'none'],['price'=>10000,'prepaymentPolicy'=>'deposit','depositType'=>'fixed','depositValue'=>9000]],'pricing'=>['payable'=>15000]];$this->assertSame(6250,BookingPrepayments::target($s,$b));$b['pricing']['payable']=0;$this->assertSame(0,BookingPrepayments::target($s,$b));
 }
 public function test_feature_default_off_missing_payment_warning_and_central_switch():void{
  $this->assertFalse(BookingPrepayments::enabled(app(SalonStore::class)->read()));$this->putJson('/api/config',$this->config(['prepaymentEnabled'=>true,'prepaymentMode'=>'full']))->assertUnprocessable();$this->configure();$b=$this->postJson('/api/bookings',$this->data())->assertCreated()->json();$this->withSession(['platform_admin'=>true]);$this->putJson('/api/platform/connections',['prepayment_enabled'=>false])->assertOk();$this->postJson('/api/manage/checkout',['token'=>$b['token']])->assertUnprocessable();$this->getJson('/api/public')->assertJsonPath('prepaymentAvailable',false);app(SalonStore::class)->mutate(fn(&$s)=>null);$this->getJson('/api/manage?token='.$b['token'])->assertJsonPath('booking.awaitingPayment',false)->assertJsonPath('booking.status','confirmed');Http::assertNothingSent();
 }
 public function test_public_quote_and_service_policy_validation():void{$this->configure(['prepaymentMode'=>'optional']);$services=app(SalonStore::class)->read()['services'];$services[0]['prepaymentPolicy']='full';$this->putJson('/api/config',['services'=>$services])->assertOk();$this->postJson('/api/quote',['services'=>['cut'],'public'=>true])->assertOk()->assertJsonPath('prepayment.requiredAmount',8500);$services[0]['depositType']='percent';$services[0]['depositValue']=101;$this->putJson('/api/config',['services'=>$services])->assertUnprocessable();}
 public function test_booking_horizon_is_enforced_for_guests_in_slots_and_submission_but_not_manual_admin():void{
  $this->putJson('/api/config',$this->config(['bookingHorizonMode'=>'date','bookingHorizonDate'=>'2036-05-08']))->assertOk();$this->getJson('/api/slots?date=2036-05-08&services=cut&staff=anna&public=1')->assertOk();$this->assertNotEmpty($this->getJson('/api/slots?date=2036-05-08&services=cut&staff=anna&public=1')->json());$this->getJson('/api/slots?date=2036-05-09&services=cut&staff=anna&public=1')->assertExactJson([]);$this->postJson('/api/bookings',$this->data(['start'=>'2036-05-09T08:00:00Z']))->assertUnprocessable();$this->postJson('/api/bookings',$this->data(['start'=>'2036-05-09T08:00:00Z','public'=>false]))->assertCreated();$this->putJson('/api/config',$this->config(['bookingHorizonMode'=>'months','bookingHorizonMonths'=>3]))->assertOk();$this->assertSame('2036-08-06',BookingHorizon::end(app(SalonStore::class)->read())->format('Y-m-d'));$this->putJson('/api/config',$this->config(['bookingHorizonMode'=>'date','bookingHorizonDate'=>null]))->assertUnprocessable();
 }
 public function test_barion_requires_authenticated_matching_state_and_is_idempotent():void{
  $this->configure(['paymentProvider'=>'barion']);app(Connections::class)->save(['barion_pos_key'=>(string)Str::uuid(),'barion_payee'=>'merchant@example.com','barion_environment'=>'sandbox']);$paymentId=str_replace('-','',(string)Str::uuid());$ref=null;Http::fake(function($r)use($paymentId,&$ref){$ref=$r['PaymentRequestId'];$this->assertSame(2550,$r['Transactions'][0]['Total']);$this->assertSame('merchant@example.com',$r['Transactions'][0]['Payee']);return Http::response(['PaymentId'=>$paymentId,'GatewayUrl'=>'https://secure.test.barion.com/Pay?id='.$paymentId]);});$b=$this->postJson('/api/bookings',$this->data())->assertCreated()->json();$this->postJson('/api/manage/checkout',['token'=>$b['token'],'mode'=>'deposit','amount'=>1])->assertOk();$this->postJson('/api/barion/callback',['PaymentId'=>(string)Str::uuid(),'Status'=>'Succeeded'])->assertStatus(409);$state=['PaymentId'=>$paymentId,'PaymentRequestId'=>$ref,'Currency'=>'HUF','Total'=>1,'Status'=>'Succeeded'];Http::swap(new \Illuminate\Http\Client\Factory());Http::preventStrayRequests();Http::fake(['api.test.barion.com/v4/*'=>Http::response($state)]);$this->postJson('/api/barion/callback',['PaymentId'=>$paymentId,'Total'=>2550])->assertUnprocessable();$this->assertCount(0,app(SalonStore::class)->read()['payments']);$state['Total']=2550;Http::swap(new \Illuminate\Http\Client\Factory());Http::preventStrayRequests();Http::fake(['api.test.barion.com/v4/*'=>Http::response($state)]);$this->postJson('/api/barion/callback',['PaymentId'=>$paymentId])->assertOk();$this->postJson('/api/barion/callback',['PaymentId'=>$paymentId])->assertOk();$this->assertCount(1,app(SalonStore::class)->read()['payments']);$this->getJson('/api/manage?token='.$b['token'])->assertJsonPath('booking.status','confirmed');Http::assertSent(fn($r)=>str_contains($r->url(),'/paymentstate')&&$r->hasHeader('x-pos-key'));
 }
 public function test_szep_uses_a_separate_merchant_32_alphanumeric_reference_and_signed_ipn():void{
  $this->configure();app(Connections::class)->save(['simplepay_merchant'=>'NORMAL','simplepay_secret'=>'normal-secret','simplepay_szep_merchant'=>'SZEP_ONLY','simplepay_szep_secret'=>'szep-secret','simplepay_szep_environment'=>'sandbox']);$ref=null;Http::fake(function($r)use(&$ref){$v=$r->data();$this->assertSame('SZEP_ONLY',$v['merchant']);$this->assertSame(['CARD'],$v['methods']);$ref=$v['orderRef'];$this->assertMatchesRegularExpression('/^[a-f0-9]{32}$/',$ref);$body=json_encode(['transactionId'=>'szep-123','paymentUrl'=>'https://sandbox.simplepay.hu/pay/szep']);return Http::response($body,200,['Signature'=>SimplePay::signature($body,'szep-secret')]);});$b=$this->postJson('/api/bookings',$this->data())->assertCreated()->json();$this->postJson('/api/manage/checkout',['token'=>$b['token'],'mode'=>'deposit','rail'=>'szep'])->assertOk();$this->assertCount(0,app(SalonStore::class)->read()['payments']);$ipn=json_encode(['merchant'=>'SZEP_ONLY','orderRef'=>$ref,'status'=>'FINISHED','transactionId'=>'szep-123']);$body=json_encode(['transactions'=>[['orderRef'=>$ref,'transactionId'=>'szep-123','status'=>'FINISHED','currency'=>'HUF','total'=>2550]]]);Http::swap(new \Illuminate\Http\Client\Factory());Http::preventStrayRequests();Http::fake(['sandbox.simplepay.hu/payment/v2/query'=>Http::response($body,200,['Signature'=>SimplePay::signature($body,'szep-secret')])]);$this->call('POST','/api/simplepay/ipn',[],[],[],['CONTENT_TYPE'=>'application/json','HTTP_SIGNATURE'=>SimplePay::signature($ipn,'szep-secret')],$ipn)->assertStatus(400);for($i=0;$i<2;$i++)$this->call('POST','/api/simplepay/szep-ipn',[],[],[],['CONTENT_TYPE'=>'application/json','HTTP_SIGNATURE'=>SimplePay::signature($ipn,'szep-secret')],$ipn)->assertOk();$s=app(SalonStore::class)->read();$this->assertCount(1,$s['payments']);$this->assertSame('szep',$s['payments'][0]['method']);$this->assertSame('confirmed',$s['bookings'][0]['status']);
 }
 public function test_sms_minimum_transfer_requires_verified_operator_credit_and_unique_bank_reference():void{
  config(['operator.name'=>'Üzemeltető','operator.account'=>'87654321-87654321']);$request=(string)Str::uuid();$this->postJson('/api/sms-wallet',['amount'=>2000,'requestId'=>$request,'acceptPrice'=>true])->assertUnprocessable();$t=$this->postJson('/api/sms-wallet/transfer',['amount'=>3000,'requestId'=>$request,'acceptPrice'=>true])->assertOk()->assertJsonPath('status','awaiting_transfer')->json();$this->assertSame(0,SmsWallet::info(1)['balance']);$v=['providerId'=>1,'amount'=>3000,'bankReference'=>'BANK-UNIQUE-1','topupId'=>$t['id'],'confirmed'=>true];$this->postJson('/api/platform/sms-wallet/credit',$v)->assertForbidden();$this->withSession(['platform_admin'=>true]);$this->postJson('/api/platform/sms-wallet/credit',array_replace($v,['amount'=>5000]))->assertUnprocessable();$this->postJson('/api/platform/sms-wallet/credit',$v)->assertOk();$this->postJson('/api/platform/sms-wallet/credit',$v)->assertOk()->assertJsonPath('alreadyCredited',true);$this->assertSame(3000,SmsWallet::info(1)['balance']);$this->assertSame(1,DB::table('sms_ledger')->count());$this->postJson('/api/platform/sms-wallet/credit',array_replace($v,['bankReference'=>' bank-unique-1 ']))->assertOk()->assertJsonPath('alreadyCredited',true);$this->postJson('/api/platform/sms-wallet/credit',array_replace($v,['providerId'=>2,'topupId'=>null]))->assertUnprocessable();$this->postJson('/api/platform/sms-wallet/credit',['providerId'=>2,'amount'=>5000,'bankReference'=>'BANK-UNIQUE-2','confirmed'=>true])->assertOk();$this->assertSame(5000,SmsWallet::info(2)['balance']);Http::assertNothingSent();
 }
 public function test_a_previously_started_2000_huf_card_topup_can_still_be_settled_after_the_minimum_changes():void{
  $id=(string)Str::uuid();DB::table('sms_topups')->insert(['id'=>$id,'provider_id'=>1,'request_id'=>(string)Str::uuid(),'amount'=>2000,'status'=>'pending','session_id'=>'cs_legacy','created_at'=>now(),'updated_at'=>now()]);$o=['id'=>'cs_legacy','metadata'=>['type'=>'sms_topup','provider_id'=>'1','topup_id'=>$id],'currency'=>'huf','amount_total'=>200000,'payment_status'=>'paid'];
  \App\Services\SmsTopups::webhook(['type'=>'checkout.session.completed'],$o);\App\Services\SmsTopups::webhook(['type'=>'checkout.session.completed'],$o);$this->assertSame(2000,SmsWallet::info(1)['balance']);$this->assertSame([3000,5000,10000],SmsWallet::info(1)['packages']);
 }

 public function test_fully_paid_szep_bookings_keep_the_payment_method_on_both_invoice_gateways():void{
  foreach(['billingo','szamlazz'] as $index=>$gateway){$b=$this->postJson('/api/bookings',$this->data(['public'=>false,'start'=>'2036-05-'.(10+$index).'T08:00:00Z']))->assertCreated()->json();$p=$this->postJson('/api/payments',['bookingId'=>$b['id'],'amount'=>8500,'method'=>'card','paidAt'=>now()->toISOString()])->assertCreated()->json();app(SalonStore::class)->mutate(function(&$s)use($p,$gateway){foreach($s['payments'] as &$payment)if($payment['id']===$p['id']){$payment['method']='szep';$payment['source']='simplepay';}$s['settings']['invoiceProvider']=$gateway;});
   app(Connections::class)->save(['billingo_key'=>'fake','billingo_block'=>1,'szamlazz_key'=>'fake']);Http::swap(new \Illuminate\Http\Client\Factory());Http::preventStrayRequests();Http::fake(['api.billingo.hu/v3/partners'=>Http::response(['id'=>10]),'api.billingo.hu/v3/documents'=>Http::response(['id'=>20,'invoice_number'=>'TEST-SZEP']),'www.szamlazz.hu/szamla/'=>Http::response('<?xml version="1.0"?><xmlszamlavalasz><sikeres>true</sikeres><szamlaszam>TEST-SZEP</szamlaszam></xmlszamlavalasz>')]);$this->postJson('/api/invoices',['paymentId'=>$p['id'],'buyer'=>['name'=>'Teszt Vevő','email'=>'buyer@example.com','country'=>'HU','zip'=>'1111','city'=>'Budapest','address'=>'Teszt utca 1.']])->assertOk()->assertJsonPath('number','TEST-SZEP');
   if($gateway==='billingo')Http::assertSent(fn($r)=>str_ends_with($r->url(),'/documents')&&$r['payment_method']==='szep_card');else Http::assertSent(fn($r)=>str_contains($r->body(),'<fizmod>SZÉP kártya</fizmod>'));
  }
 }

 public function test_prepayment_methods_are_filtered_and_disallowed_card_requests_cannot_start_a_payment():void{
  $this->configure(['prepaymentMethods'=>['transfer']]);app(Connections::class)->save(['stripe_key'=>'fake','stripe_webhook_secret'=>'fake']);$b=$this->postJson('/api/bookings',$this->data())->assertCreated()->json();$this->getJson('/api/manage?token='.$b['token'])->assertJsonPath('prepayment.cardReady',false)->assertJsonPath('prepayment.szepReady',false)->assertJsonPath('prepayment.account','12345678-12345678');
  foreach(['card','szep'] as $rail)$this->postJson('/api/manage/checkout',['token'=>$b['token'],'rail'=>$rail])->assertUnprocessable();Http::assertNothingSent();
  $this->putJson('/api/config',$this->config(['prepaymentMethods'=>[]]))->assertUnprocessable();$this->putJson('/api/config',$this->config(['prepaymentMethods'=>['szep']]))->assertUnprocessable();$this->putJson('/api/config',$this->config(['prepaymentMethods'=>['cash']]))->assertUnprocessable();
  $this->putJson('/api/config',$this->config(['prepaymentMethods'=>['card']]))->assertOk();$this->getJson('/api/manage?token='.$b['token'])->assertJsonPath('prepayment.cardReady',true)->assertJsonPath('prepayment.account','');
 }

